package main

import (
    "encoding/json"
    "fmt"
    "net/http"
    "net/http/httptest"
)

var host string
var port int

type Server struct {
    Host string `json:"host"`
    Port int    `json:"port"`
}

func serverHandler(w http.ResponseWriter, r *http.Request) {
    w.Header().Set("Content-Type", "application/json")
    server := Server{Host: host, Port: port}
    json.NewEncoder(w).Encode(server)
}

// ---- ここから下は動作確認用(書き換えない)。ネットワークを使わずにハンドラーを1回呼び、結果を表示する ----
func main() {
    fmt.Scan(&host, &port)
    rec := httptest.NewRecorder()
    serverHandler(rec, httptest.NewRequest("GET", "/server", nil))
    res := rec.Result()
    fmt.Println("Content-Type:", res.Header.Get("Content-Type"))
    fmt.Print(rec.Body.String())
}

```go
type Server struct {
    Host string `json:"host"`
    Port int    `json:"port"`
}

func serverHandler(w http.ResponseWriter, r *http.Request) {
    w.Header().Set("Content-Type", "application/json")
    server := Server{Host: "tokyo", Port: 8080}
    json.NewEncoder(w).Encode(server)
}

// main() 内に追加
http.HandleFunc("/server", serverHandler)
```
返したい JSON は host が文字列、port が数値で型が混ざっています。map[string]string は値をすべて string にする必要があり、8080 を "8080" という文字列で返すことになってデータとして不正確です。構造体ならフィールドごとに型を変えられ、JSON タグで小文字のキー名にもできます。
